def solve(graph: dict[int, list[int]], start: int, goal: int) -> int:
    if start == goal:
        return 0
    visited = set()
    queue = [(start, 0)]

    while queue:
        node, hops = queue.pop(0)
        if node == goal:
            return hops
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                queue.append((neighbor, hops + 1))
    return -1

