def solve(records):
    grouped = {}
    for date, amount in records:
        month_year = date[:7]  # Extract YYYY-MM
        if month_year not in grouped:
            grouped[month_year] = 0
        grouped[month_year] += amount
    return sorted([(month_year, total) for month_year, total in grouped.items() if total != 0], key=lambda x: x[0])

