        if line.endswith('\r\n'):
            line = line[:-2]
        fields = []
        field = ''
        in_quote = False
        for char in line:
            if char == '"':
                in_quote = not in_quote
            elif char == ',' and not in_quote:
                if field:
                    fields.append(field)
                    field = ''
            elif char == '\r':
                continue  # Skip bare CR
            field += char
        if field:  # Add the last field if it's not empty
            fields.append(field)
        return fields

