def prime_factors(n, prime: int = 2):
    factors = []
    while n % prime == 0:
        factors.append(prime)
        n //= prime
    prime += 1
    while prime * prime <= n:
        if n % prime == 0:
            factors.append(prime)
            n //= prime
        prime += 1
    if n > 1:
        factors.append(n)
    return factors

def lcm(a, b):
    return abs(a * b) // gcd(a, b)

def solve(congruences: list[list[int]]) -> list[int] | None:
    a, b, r = 0, 1, 0
    moduli = [1]
    for remainder, modulus in congruences:
        if remainder < 0:
            remainder += modulus
        if remainder == 0:
            return [r, m]
        factors = prime_factors(modulus)
        for prime in factors:
            lcm_val = lcm(lcm_val, prime)
        a = (a * lcm_val - remainder) % lcm_val
        b = (b * lcm_val) % lcm_val
        moduli.extend([lcm_val] * len(factors))
        r = (r * a * b % lcm_val) % lcm_val
    return [r, lcm(*moduli)]

