    def decode_tilde(s):
        return s.replace('~1', '/').replace('~0', '~')

    def is_valid_pointer(pointer):
        tokens = pointer.lstrip('/').split('/')[1:]
        for token in tokens:
            if token.isdigit():
                if token[0] == '0':
                    return False
            elif token.startswith('~'):
                return False
            elif token.startswith('-') or not token:
                return False
        return True

    def find_value(doc, pointer):
        tokens = decode_tilde(pointer).split('/')
        ptr = doc
        for token in tokens:
            if isinstance(ptr, list):
                try:
                    idx = int(token)
                    if idx < 0 or idx >= len(ptr):
                        return [False, None]
                    ptr = ptr[idx]
                except ValueError:
                    return [False, None]
            else:
                if token not in ptr:
                    return [False, None]
                ptr = ptr[token]
        return [True, ptr]

    return [find_value(document, ptr) for ptr in pointers]

