        parts = ptr.split('/')
        decoded = []
        for part in parts:
            decoded.append(re.sub('~(0|1)', r'~' + part[0], part[1:]))
        return decoded

    def traverse(document, path):
        for ptr in path:
            if isinstance(document, dict):
                key = decode_pointer(ptr)[0]
                if key in document:
                    document = document[key]
                else:
                    return [False, None]
            elif isinstance(document, list):
                index = decode_pointer(ptr)
                index = int(index[0])
                if 0 <= index < len(document):
                    document = document[index]
                else:
                    return [False, None]
            else:
                return [False, None]
        return [True, document]

    results = []
    for ptr in pointers:
        result = traverse(document, decode_pointer(ptr))
        results.append(result)
    return results

