    def resolve(pointer):
        current = document
        for part in pointer.split('/'):
            if part == '':
                return current
            elif part.lstrip('~') == '':
                return [resolve(current[index]) for index in range(len(current))]
            elif part.count('~') == 1:
                index = part.replace('~1', '/').replace('~0', '~')
                if index.isdigit():
                    index = int(index)
                    if 0 <= index < len(current):
                        return resolve(current[index])
                else:
                    return False, None
            else:
                return False, None

    return [[resolve(document), None] if not resolve(document) else [False, None] for point in pointers]

