                if fragment[1] != fragments[fragment[0] - 1][1]:
                    return None

    if overlapping:
        return overlapping.pop()

    return None

def solve(length, fragments):
    if len(fragments) == 0:
        if length == 0:
            return ''
        else:
            return None

    offsets = [f[0] for f in fragments]
    text = ''.join(f[1] for f in fragments)

    for i in range(length):
        if offsets[i] < i:
            # Overlapping characters conflict
            return None

    # Check if all positions are covered
    for i in range(length):
        if offsets[i] + len(fragments[i][1]) > i:
            # Position uncovered
            return None

    return text

