def solve(grid: list[list[int | None]]) -> list | None:
    if not grid or not grid[0]:
        return None

    rows, cols = len(grid), len(grid[0])
    min_sum = float('inf')
    best_route = None

    def dfs(x, y, path):
        nonlocal min_sum, best_route

        if x >= rows or y >= cols or grid[x][y] is None:
            return

        if x == rows - 1 and y == cols - 1:
            current_sum = sum(grid[i][j] for i in range(rows) for j in range(cols) if grid[i][j] is not None)
            if current_sum < min_sum:
                min_sum = current_sum
                best_route = path[:]
                return

        dfs(x + 1, y, path + 'D')
        dfs(x, y + 1, path + 'R')

    dfs(0, 0, '')

    return [min_sum, len(best_route), best_route]

from typing import List, Optional

def solve(grid: List[List[Optional[int | None]]]) -> List[int | None]:
    if not grid or not grid[0]:
        return None

    rows, cols = len(grid), len(grid[0])
    if rows == 1 and cols == 1:
        return [grid[0][0], 1, "D"]

    queue = [(0, 0, 0)]
    directions = [(1, 0), (0, 1)]
    visited = set()
    min_sum = float('inf')
    min_routes = 0
    current_path = ''

    while queue:
        x, y, current_sum = queue.pop(0)

        if (x, y) == (rows - 1, cols - 1):
            if current_sum < min_sum:
                min_sum = current_sum
                min_routes = 1
                current_path = ''
            elif current_sum == min_sum:
                min_routes += 1
                current_path += 'D' if x == rows - 2 else 'R'

        if (x, y) in visited:
            continue

        visited.add((x, y))

        for dx, dy in directions:
            new_x, new_y = x + dx, y + dy
            if 0 <= new_x < rows and 0 <= new_y < cols and grid[new_x][new_y] is not None:
                queue.append((new_x, new_y, current_sum + grid[new_x][new_y]))

    if min_routes == 0:
        return None

    return [min_sum, min_routes, current_path]

