import datetime

def solve(year: int, week: int, weekday: int) -> str | None:
    if not (1 <= year <= 9999): return None
    if not (1 <= week <= 53): return None
    if not (1 <= weekday <= 7): return None

    jan4_2025 = datetime.date(year=2025, month=1, day=4)
    jan4_2025_iso = jan4_2025.isocalendar()

    if (year, week) == jan4_2025_iso:
        return jan4_2025.strftime('%Y-%m-%d')

    jan4_2025_delta = datetime.timedelta(days=jan4_2025_iso.weekday() - weekday - 1)
    jan4_2025_plus_week = jan4_2025 + jan4_2025_delta

    return jan4_2025_plus_week.strftime('%Y-%m-%d')

from datetime import datetime, timedelta

def solve(year: int, week: int, weekday: int) -> str | None:
    if not (1 <= year <= 9999):
        return None
    if not (1 <= week <= 53):
        return None
    if weekday < 1 or weekday > 7:
        return None

    # Calculate the first day of the given week
    first_day_of_week = datetime(year, 1, 4)
    offset = (weekday - 1) % 7  # Adjust for the weekday being 1-based
    first_day_of_week += timedelta(days=offset)

    # Calculate the end of the given week
    last_day_of_week = first_day_of_week + timedelta(days=6)
    if last_day_of_week.year != year:
        last_day_of_week = first_day_of_week + timedelta(days=5)

    # If the week is at the end of a year, add one year
    if week == 53 and first_day_of_week.month != 1:
        first_day_of_week += timedelta(days=7)
        last_day_of_week += timedelta(days=7)

    # Verify if the calculated week and date fall within the valid range
    if first_day_of_week.year != year or last_day_of_week.year != year:
        return None
    if first_day_of_week > last_day_of_week:
        return None

    # Return the Gregorian date in YYYY-MM-DD format
    return first_day_of_week.strftime('%Y-%m-%d')

