import math

def solve(n: int, places: int) -> str:
    sqrt_value = math.sqrt(n)
    if places > 0:
        sqrt_value = round(sqrt_value, places)
    return f"{int(sqrt_value)}.{'0' * places}" if sqrt_value == int(sqrt_value) else f"{sqrt_value:.{places}f}"

def solve(n, places):
    if n == 0:
        return "0"
    is_positive = n >= 0
    n = abs(n)
    sqrt = sqrt(n)
    if not places:
        return str(sqrt)
    sqrt_str = str(sqrt)
    if len(sqrt_str) > places:
        sqrt_str = sqrt_str[:places] + sqrt_str[places:].rstrip('0')
    if not is_positive:
        sqrt_str = '-' + sqrt_str
    return sqrt_str

