def solve(jobs):
    if not jobs:
        return []

    # Sort the jobs by end time and weight in descending order
    jobs.sort(key=lambda x: (-x[1], -x[2]))

    def conflict(job1, job2):
        return job1[0] < job2[1] and job2[0] < job1[1]

    def dfs(i, weight, chosen):
        if i == len(jobs):
            return [-1] if weight < 0 else chosen
        if weight >= jobs[i][2]:
            chosen_i = dfs(i + 1, weight - jobs[i][2], chosen + [i])
            if chosen_i != -1:
                return chosen_i
        return dfs(i + 1, weight, chosen)

    max_weight = 0
    best_indices = []
    for i in range(len(jobs)):
        if jobs[i][2] > max_weight:
            max_weight = jobs[i][2]
            best_indices = [i]

    for i in range(1, len(jobs)):
        for chosen in combinations(best_indices, i):
            if not any(conflict(jobs[j], jobs[i]) for j in chosen):
                chosen_i = dfs(i + 1, max_weight, chosen)
                if chosen_i != -1:
                    return chosen_i

    return []

