from operator import add

def solve(text: str) -> int:
    # Initialize a 2D array to store the count of distinct palindromic subsequences
    dp = [[0 for _ in range(len(text) + 1)] for _ in range(len(text) + 1)]

    # Base case: There is exactly one subsequence for any single character
    for i in range(len(text)):
        dp[i][i] = 1

    # Fill the DP table
    for length in range(2, len(text) + 1):
        for start in range(len(text) - length + 1):
            end = start + length - 1
            if text[start] == text[end] and (start == end or dp[start + 1][end - 2] > 0):
                dp[start][end] = (2 + dp[start + 1][end - 1]) % 1000000007
            else:
                dp[start][end] = add(dp[start + 1][end], dp[start][end - 1], dp[start + 1][end - 2]) % 1000000007

    # The answer is the count of distinct palindromic subsequences of the entire string
    return dp[0][len(text) - 1]

